import { test, expect } from '@playwright/test';

test.describe('Modal Accessibility - Title Announcement', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <html>
        <head>
          <title>Modal Accessibility Test</title>
        </head>
        <body>
          <button id="openModal">Open Modal</button>

          <div id="modal" role="dialog" aria-labelledby="modalTitle" aria-modal="true" style="display: none; position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); background: white; padding: 20px; border: 1px solid black; z-index: 1000;">
            <h2 id="modalTitle">Confirm Action</h2>
            <p>Are you sure you want to proceed?</p>
            <button id="confirmBtn">Confirm</button>
            <button id="cancelBtn">Cancel</button>
          </div>

          <div id="overlay" style="display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5); z-index: 999;"></div>

          <script>
            const openBtn = document.getElementById('openModal');
            const modal = document.getElementById('modal');
            const overlay = document.getElementById('overlay');
            const cancelBtn = document.getElementById('cancelBtn');

            openBtn.addEventListener('click', () => {
              modal.style.display = 'block';
              overlay.style.display = 'block';
              modal.focus();
            });

            cancelBtn.addEventListener('click', () => {
              modal.style.display = 'none';
              overlay.style.display = 'none';
            });
          </script>
        </body>
      </html>
    `);
  });

  test('should have proper ARIA attributes for modal title announcement', async ({ page }) => {
    const modal = page.locator('#modal');
    const modalTitle = page.locator('#modalTitle');

    // Verify modal has role="dialog"
    await expect(modal).toHaveAttribute('role', 'dialog');

    // Verify modal has aria-labelledby pointing to title
    await expect(modal).toHaveAttribute('aria-labelledby', 'modalTitle');

    // Verify modal has aria-modal="true"
    await expect(modal).toHaveAttribute('aria-modal', 'true');

    // Verify title element exists and has correct id
    await expect(modalTitle).toHaveAttribute('id', 'modalTitle');
    await expect(modalTitle).toContainText('Confirm Action');
  });

  test('should announce modal title when modal is opened', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const modal = page.locator('#modal');
    const modalTitle = page.getByRole('heading', { name: 'Confirm Action' });

    // Initially modal should be hidden
    await expect(modal).toHaveCSS('display', 'none');

    // Click to open modal
    await openButton.click();

    // Modal should now be visible
    await expect(modal).toHaveCSS('display', 'block');

    // Title should be visible and accessible
    await expect(modalTitle).toBeVisible();

    // Verify the modal's aria-labelledby correctly references the title
    const ariaLabelledBy = await modal.getAttribute('aria-labelledby');
    expect(ariaLabelledBy).toBe('modalTitle');

    // Verify title text is present
    const titleText = await modalTitle.textContent();
    expect(titleText).toBe('Confirm Action');
  });

  test('should maintain accessibility attributes when modal is closed and reopened', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const cancelButton = page.getByRole('button', { name: 'Cancel' });
    const modal = page.locator('#modal');

    // Open modal first time
    await openButton.click();
    await expect(modal).toHaveCSS('display', 'block');

    // Verify accessibility attributes are present
    await expect(modal).toHaveAttribute('role', 'dialog');
    await expect(modal).toHaveAttribute('aria-labelledby', 'modalTitle');
    await expect(modal).toHaveAttribute('aria-modal', 'true');

    // Close modal
    await cancelButton.click();
    await expect(modal).toHaveCSS('display', 'none');

    // Open modal again
    await openButton.click();
    await expect(modal).toHaveCSS('display', 'block');

    // Verify accessibility attributes are still present
    await expect(modal).toHaveAttribute('role', 'dialog');
    await expect(modal).toHaveAttribute('aria-labelledby', 'modalTitle');
    await expect(modal).toHaveAttribute('aria-modal', 'true');
  });

  test('should have accessible modal content structure', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });

    // Open modal
    await openButton.click();

    // Verify modal heading is properly structured
    const heading = page.getByRole('heading', { level: 2, name: 'Confirm Action' });
    await expect(heading).toBeVisible();

    // Verify modal contains accessible buttons
    const confirmButton = page.getByRole('button', { name: 'Confirm' });
    const cancelButton = page.getByRole('button', { name: 'Cancel' });

    await expect(confirmButton).toBeVisible();
    await expect(cancelButton).toBeVisible();

    // Verify modal text content is accessible
    const modalText = page.locator('#modal').locator('p');
    await expect(modalText).toContainText('Are you sure you want to proceed?');
  });
});
